}","new_string":"/**
 * The first cycle a name-ordered depth-first search meets, walking each task's
 * dependencies in name order.
 * @param tasks - the parsed graph.
 * @returns the cycle as names from the repeated task back to itself, or `undefined` when the graph is acyclic.
 */
export function findCycle(tasks) {
  const visiting = new Set() // tasks currently in the DFS stack
  const stack = [] // the actual DFS stack

  const dfs = (name) => {
    if (visiting.has(name)) {
      // Found a cycle! Extract it from the stack.
      const cycleStart = stack.findIndex(n => n === name)
      const cycle = stack.slice(cycleStart)
      return cycle.concat([name])
    }

    visiting.add(name)
    stack.push(name)

    const task = tasks.get(name)
    for (const dep of task.deps) {
      const result = dfs(dep)
      if (result) return result
    }

    stack.pop()
    visiting.delete(name)
    return undefined
  }

  // Try starting from each task in ascending order
  for (const name of [...tasks.keys()].sort()) {
    visiting.clear()
    stack.length = 0
    const result = dfs(name)
    if (result) return result
  }

  return undefined
}"}

